    const ticks=Number(spawnSync('getconf',['CLK_TCK'],{encoding:'utf8'}).stdout.trim());
    assert.ok(Number.isFinite(ticks)&&ticks>0);
    const findWorkerd=async()=>{
      const tasks=await fs.readdir('/proc/'+process.pid+'/task');const pids=new Set();for(const tid of tasks){try{for(const pid of (await fs.readFile('/proc/'+process.pid+'/task/'+tid+'/children','utf8')).trim().split(/\s+/).filter(Boolean))pids.add(pid);}catch{}}const children=[...pids];
      const matches=[];for(const pid of children){try{if((await fs.readFile('/proc/'+pid+'/comm','utf8')).trim().startsWith('workerd'))matches.push(pid);}catch{}}
      assert.equal(matches.length,1,'one workerd child for process CPU');return matches[0];
    };
    const processCpu=async pid=>{const stat=await fs.readFile('/proc/'+pid+'/stat','utf8');const fields=stat.slice(stat.lastIndexOf(') ')+2).trim().split(/\s+/);return (Number(fields[11])+Number(fields[12]))*1000/ticks;};
    for(const verified of [false,true,false,true]){
      await configure(verified?options():options({verifyCertificate:false,caCertificates:undefined}));
      assertEchAnswer(await requestPublic());
      const pid=await findWorkerd();const before=await processCpu(pid);const start=performance.now();
      for(let i=0;i<20;i++)assertEchAnswer(await requestPublic());
      const wallMs=performance.now()-start;const cpuMs=(await processCpu(pid))-before;assert.equal(await findWorkerd(),pid);assert.ok(cpuMs>=0);
      console.log(JSON.stringify({evidenceKind:'Linux workerd whole-process CPU; not platform quota CPU',verified,successfulHandshakes:20,processCpuMs:cpuMs,perHandshakeProcessCpuMs:cpuMs/20,wallMs,clockTicks:ticks,onlineRequests:0,scope:'Warm local independent TLS fixture; true uses explicit fixture CA, not public bundled-root validation'}));
    }
`;
